/* Manage funnel messages in the context of installed extension. */
import {
  STORAGE_KEY,
  TARGET,
  VERSION,
} from './constants.js';

const defaultMessage = {
  addon: TARGET,
  version: VERSION,
};

// Set the storage key early to help the applications detect if the user is using the extension
sessionStorage.setItem(STORAGE_KEY, '1');

const sendMessage = (event) => {
  window.postMessage(JSON.stringify({ ...defaultMessage, event }), '*');
};

window.addEventListener('load', () => {
  sendMessage('version');
});
